const $=<T extends HTMLElement=HTMLElement>(q:string)=>document.querySelector<T>(q)!;
const esc=(value:unknown)=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
const num=(value:number|null|undefined,digits=1)=>value===null||value===undefined||!Number.isFinite(value)?'—':new Intl.NumberFormat('ru',{maximumFractionDigits:digits}).format(value);
const dateLabel=(v:string)=>new Intl.DateTimeFormat('ru',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(v.slice(0,10)+'T00:00:00Z'));
