function paintIcons(root:ParentNode=document){root.querySelectorAll<HTMLElement>('[data-icon]').forEach(e=>{if(!e.querySelector('svg'))e.insertAdjacentHTML('afterbegin',icon(e.dataset.icon!));});}
const KEY='appname-live-workspace-v1';
let farm:FarmSnapshot=createWorkspace(),storageFailure='';
try{const raw=localStorage.getItem(KEY);if(raw){const value=JSON.parse(raw),parsed=farmSchema.safeParse(value?.state?.farm??value);if(parsed.success&&!parsed.data.demo&&integrityProblems(parsed.data).length===0)farm=parsed.data;else storageFailure='Сохранённые данные не прошли проверку. Они не удалены. Загрузите корректный архив в настройках.';}}catch{storageFailure='Браузер запретил локальное сохранение или данные повреждены.';}
let season=safeStorage.get('appname-live-season')??String(new Date().getFullYear());if(!farm.seasons.some(s=>s.id===season))season=farm.seasons.at(-1)!.id;
let selectedId:string|null=null,point:Position=[67.243753,47.979811],imageDate=dateOffset(today(),-7),layer='none',map:MapAdapter|null=null,mapReady=false,drawing=false,vertices:Position[]=[],editingGeometry:string|null=null,preview:AllocationPreview|null=null;
let climate:Record<string,ClimateRecord>={},activeClimate:ApiEnvelope<ClimateDaily[]>|null=null,climateLoading=false,climateError='',climateToken=0,sourceBusy=false;
let eonetData:ApiEnvelope<NaturalEvent[]>|null=null,firmsData:ApiEnvelope<FireDetection[]>|null=null;
const undo:FarmSnapshot[]=[],redo:FarmSnapshot[]=[];
const sourceReport:Record<string,{state:string;detail:string;at:string}>={};
let route=location.pathname,toastTimer:ReturnType<typeof setTimeout>,snapshotUrl:string|null=null;
const pageNames:Record<string,string>={'/':'Карта полей','/table':'История культур','/plan':'План площадей','/risks':'Проверка рисков','/sources':'Источники данных','/settings':'Настройки'};
const chosen=()=>farm.fields.find(f=>f.id===selectedId);
const planting=(id:string,year=season)=>farm.plantings.find(p=>p.fieldId===id&&p.seasonId===year);
function toast(message:string){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,6500);}
function persist(){try{localStorage.setItem(KEY,JSON.stringify({state:{farm},version:1}));storageFailure='';}catch{storageFailure='Изменения не сохранились: проверьте доступ к localStorage и свободное место.';toast(storageFailure);}}
function change(update:(next:FarmSnapshot)=>void){const next=structuredClone(farm);update(next);const parsed=farmSchema.safeParse(next);if(!parsed.success){toast('Изменение не прошло проверку. Проверьте значения.');return false;}undo.push(structuredClone(farm));if(undo.length>20)undo.shift();redo.length=0;farm=parsed.data;preview=null;persist();render();return true;}
function historyAction(kind:'undo'|'redo'){const from=kind==='undo'?undo:redo,to=kind==='undo'?redo:undo;const next=from.pop();if(!next){toast('Нет изменений для '+(kind==='undo'?'отмены':'повтора'));return;}to.push(structuredClone(farm));farm=next;persist();render();toast(kind==='undo'?'Изменение отменено':'Изменение восстановлено');}
function state(){return {...farm,climate};}
function download(name:string,data:string,type:string){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function report(id:string,status:string,detail:string){sourceReport[id]={state:status,detail,at:new Date().toISOString()};const values=Object.values(sourceReport);const issues=values.filter(s=>['error','key','stale'].includes(s.state)).length;$('#connections-pill').innerHTML=`<span class="status-dot ${issues?'warning':values.length?'':'neutral'}"></span>${values.length?issues?`${issues} требуют внимания`:'Источники отвечают':'Подключения'}`;if(route==='/sources')renderOther();}
async function api<T>(id:string,url:string):Promise<ApiEnvelope<T>>{const response=await fetch(url,{signal:AbortSignal.timeout(60000)});const body=await response.json() as ApiEnvelope<T>;if(!body||!('status' in body))throw new Error('Сервер вернул неожиданный ответ');report(id,body.error?.code==='KEY_REQUIRED'?'key':body.status==='unavailable'?'error':body.status,(body.error?body.error.code+': '+body.error.message:null)??(body.status==='stale'?'Последний успешный ответ из кэша':body.status==='partial'?'Ответ содержит пропуски':'Ответ получен'));return body;}
function climateWindow(){if(chosen()){const s=farm.seasons.find(s=>s.id===season)!;const p=planting(selectedId!);const start=p?.plantedAt??`${s.year}-05-01`;const end=p?.harvestedAt??`${s.year}-09-30`;const latest=dateOffset(today(),-7);return [start,end<latest?end:latest];}return [dateOffset(imageDate,-29),imageDate];}
async function loadClimate(){const token=++climateToken;const field=chosen();const pos=field?centroid(field.geometry):point;const [start,end]=climateWindow();activeClimate=null;climateError='';if(start>end){climateLoading=false;climateError='Для будущего сезона наблюдений ещё нет. POWER не является прогнозом.';renderAnalysis();return;}climateLoading=true;renderAnalysis();try{const body=await api<ClimateDaily[]>('power',`/api/nasa/power?lat=${pos[1]}&lon=${pos[0]}&start=${start}&end=${end}`);if(field&&body.data)climate[`${field.id}:${season}`]={daily:body.data,source:body.source,status:body.status};if(token===climateToken)activeClimate=body;}catch(error){if(token===climateToken){climateError=error instanceof Error?error.message:'Не удалось получить POWER';report('power','error',climateError);}}finally{if(token===climateToken){climateLoading=false;renderAnalysis();if(route==='/risks')renderOther();}}}
function chart(daily:ClimateDaily[]){const values=daily.slice(-30);const valid=values.filter(d=>d.tMax!==null);if(!valid.length)return '<div class="chart-empty">Нет температурных наблюдений</div>';const lo=Math.min(...valid.map(d=>d.tMax!)),hi=Math.max(...valid.map(d=>d.tMax!));let d='',breakLine=true;values.forEach((v,i)=>{if(v.tMax===null){breakLine=true;return;}const x=i/Math.max(1,values.length-1)*240,y=52-(v.tMax-lo)/Math.max(1,hi-lo)*42;d+=`${breakLine?'M':'L'}${x.toFixed(1)},${y.toFixed(1)} `;breakLine=false;});return `<div class="mini-chart"><svg viewBox="0 0 240 64" role="img" aria-label="Максимальная температура: последние 30 дней доступного ряда"><path d="M0 52H240" stroke="var(--line)" fill="none"/><path pathLength="1" d="${d}" stroke="var(--green)" stroke-width="1.8" fill="none" stroke-linejoin="round"/><text x="0" y="63" font-size="6" fill="var(--muted)">${esc(values[0]?.date.slice(5))}</text><text x="214" y="63" font-size="6" fill="var(--muted)">${esc(values.at(-1)?.date.slice(5))}</text></svg></div>`;}
function renderAnalysis(){const field=chosen();$('#analysis-title').textContent=field?.name??'Точка на карте';const pos=field?centroid(field.geometry):point;$('#point-coordinates').textContent=`${num(Math.abs(pos[1]),5)}° ${pos[1]>=0?'N':'S'} · ${num(Math.abs(pos[0]),5)}° ${pos[0]>=0?'E':'W'}`;const body=activeClimate;const daily=body?.data??[];const goodTemps=daily.filter(d=>d.tMin!==null&&d.tMax!==null),rains=daily.filter(d=>d.precipMm!==null),soils=daily.filter(d=>d.soilMoisture!==null);const meanT=goodTemps.length?goodTemps.reduce((s,d)=>s+(d.tMin!+d.tMax!)/2,0)/goodTemps.length:null;const rain=rains.length?rains.reduce((s,d)=>s+d.precipMm!,0):null;const soil=soils.length?soils.reduce((s,d)=>s+d.soilMoisture!,0)/soils.length:null;const frost=goodTemps.length?goodTemps.filter(d=>d.tMin!<0).length:null;const [start,end]=climateWindow();$('#climate-panel').innerHTML=`<div class="section-label"><span>КЛИМАТ ТЕРРИТОРИИ</span><span class="pill">NASA POWER</span></div><div class="period">${esc(start)} — ${esc(end)}</div><div class="climate-metrics"><div><small>Температура · средняя</small><strong>${num(meanT)}<em> °C</em></strong></div><div><small>Осадки · сумма</small><strong>${num(rain)}<em> мм</em></strong></div><div><small>Влажность корней</small><strong>${num(soil,2)}<em> / 1</em></strong></div><div><small>Дни с заморозком</small><strong>${num(frost,0)}<em> дней</em></strong></div></div>${climateLoading?'<div class="chart-empty">Запрос к NASA POWER…</div>':chart(daily)}<div class="source-state ${body?.error||climateError?'error':''}"><span class="status-dot ${body?.error||climateError?'warning':climateLoading?'neutral':''}"></span>${climateLoading?'Загружаем наблюдения':esc(climateError||body?.error?.message||(body?.status==='stale'?'Источник недоступен · показан кэш':body?.status==='partial'?'Есть пропуски в ряду':body?.data?'Наблюдения получены':'Нет данных'))}</div><div class="source-caption">${daily.length?`Температура: ${goodTemps.length}/${daily.length} дней · осадки: ${rains.length}/${daily.length}. Суммы рассчитаны только по доступным дням.<br>`:''}${body?.source?.observedAt?`Наблюдения по ${esc(body.source.observedAt)}.<br>`:''}${body?.cache?.fetchedAt?`Получено: ${esc(new Date(body.cache.fetchedAt).toLocaleString('ru'))}.<br>`:''}${esc(body?.source?.datasetId??'NASA POWER')} · региональная сетка, не датчик поля.${body?.source?.timeStandard?' Временной стандарт: '+esc(body.source.timeStandard)+'.':''} GWETROOT — доля насыщения корневого слоя, не объёмная влажность.</div>`;if(field){const p=planting(field.id),crop=cropById(p?.cropId??'');const findings=evaluateField(field.id,season,state());$('#field-analysis').innerHTML=`<div class="section-label"><span>МОЁ ПОЛЕ</span><span class="pill">${esc(season)}</span></div><h3>${esc(field.name)}</h3><p>${num(field.areaHa)} га · ${esc(crop?.name??'Культура не назначена')}</p><button class="btn small" data-action="edit-field" data-id="${esc(field.id)}">Граница и назначение ↗</button>${findings.slice(0,3).map(f=>`<div class="source-caption">${esc(f.message)}</div>`).join('')}`;}else $('#field-analysis').innerHTML='<div class="section-label"><span>ДАННЫЕ ПОД ВАШИМ КОНТРОЛЕМ</span></div><h3>Настоящие поля. Ваша история.</h3><p>Границы и культуры добавляете вы. Климат и снимки поступают из NASA. Система не определяет культуру по цвету спутникового изображения.</p>';paintIcons($('#climate-panel'));}
function geoData(){return {type:'FeatureCollection',features:farm.fields.map(f=>({type:'Feature',id:f.id,geometry:f.geometry,properties:{id:f.id,name:f.name,label:`${f.name}\n${num(f.areaHa)} га`,color:cropById(planting(f.id)?.cropId??'')?.color??'#8C9E7D'}}))};}
function updateDrawing(){if(mapReady){map?.getSource('drawing')?.setData({type:'FeatureCollection',features:vertices.length?[{type:'Feature',properties:{},geometry:vertices.length===1?{type:'Point',coordinates:vertices[0]}:{type:'LineString',coordinates:vertices}}]:[]});}$('#vertex-count').textContent=vertices.length+' вершин';}
function render(){const total=farm.fields.reduce((s,f)=>s+f.areaHa,0),assigned=farm.plantings.filter(p=>p.seasonId===season).reduce((s,p)=>s+p.areaHa,0);$('#total-area').innerHTML=`${num(total)}<em> га</em>`;$('#field-count').innerHTML=`${farm.fields.length}<em> контуров</em>`;$('#assigned-area').innerHTML=`${num(assigned)}<em> га</em>`;$('#map-field-count').textContent=String(farm.fields.length);$('#season').innerHTML=farm.seasons.map(s=>`<option value="${s.id}" ${s.id===season?'selected':''}>${s.year}</option>`).join('');$('#map-empty').hidden=farm.fields.length>0||drawing;$('#fields-list').innerHTML=farm.fields.length?farm.fields.map(f=>`<button class="field-row ${selectedId===f.id?'selected':''}" data-action="select-field" data-id="${esc(f.id)}"><span class="crop-dot" style="background:${esc(cropById(planting(f.id)?.cropId??'')?.color??'#A0A98F')}"></span><span><b>${esc(f.name)}</b><small>${esc(cropById(planting(f.id)?.cropId??'')?.name??'Без назначения')}</small></span><span class="field-area">${num(f.areaHa)} га</span></button>`).join(''):'<div class="empty-fields">Здесь появятся ваши поля. Нарисуйте контур или импортируйте GeoJSON.</div>';document.querySelector<HTMLButtonElement>('[data-action=undo]')!.disabled=!undo.length;document.querySelector<HTMLButtonElement>('[data-action=redo]')!.disabled=!redo.length;if(mapReady){map?.getSource('fields')?.setData(geoData());map?.setFilter('field-selected',['==',['get','id'],selectedId??'']);}renderAnalysis();renderRoute();paintIcons();}
const motionAllowed=()=>!window.matchMedia('(prefers-reduced-motion: reduce)').matches;
function enterPage(){if(!motionAllowed())return;const page=route==='/'?$('#map-page'):$('#other-page');page.querySelectorAll<HTMLElement>('.page-heading,.overview,.map-workspace,.notice,.table-wrap,.card').forEach((element,index)=>{element.animate([{opacity:0,transform:'translateY(10px)'},{opacity:1,transform:'translateY(0)'}],{duration:360,delay:Math.min(index*35,140),easing:'cubic-bezier(.16,1,.3,1)',fill:'backwards'});});}
async function closeModalAnimated(){const modal=$<HTMLDialogElement>('#modal');if(!modal.open)return;if(motionAllowed()){await modal.animate([{opacity:1,transform:'translateY(0) scale(1)'},{opacity:0,transform:'translateY(6px) scale(.985)'}],{duration:130,easing:'ease-in',fill:'forwards'}).finished.catch(()=>{});modal.getAnimations().forEach(animation=>animation.cancel());}modal.close();}
function navigate(path:string){if(!pageNames[path])path='/';if(location.pathname!==path)history.pushState({},'',path);const changed=route!==path;route=path;document.body.classList.remove('nav-open');renderRoute();if(changed)enterPage();if(path==='/')setTimeout(()=>map?.resize(),0);}
function renderRoute(){if(!pageNames[route])route='/';$('#map-page').hidden=route!=='/';$('#other-page').hidden=route==='/';$('#breadcrumb').textContent=pageNames[route];document.title=`${pageNames[route]} — AppName`;document.querySelectorAll<HTMLElement>('nav [data-route]').forEach(a=>{a.classList.toggle('active',a.dataset.route===route);if(a.dataset.route===route)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});if(route!=='/')renderOther();}
function heading(kicker:string,title:string,description:string,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}<span>.</span></h1><p>${description}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`;}
const emptyFields=()=>`<div class="card"><div class="empty-state"><span class="state-icon">${icon('map')}</span><h2>Сначала добавьте свои поля</h2><p>В этом пространстве нет демо-контуров и вымышленной истории. Нарисуйте границы на карте или загрузите GeoJSON — затем назначайте культуры и планируйте площади.</p><button class="btn primary" data-action="draw">${icon('plus')}Нарисовать поле</button><button class="btn" data-action="import">${icon('upload')}Импорт GeoJSON</button></div></div>`;
function renderOther(){let html='';if(route==='/table'){html=heading('КАЖДЫЙ СЕЗОН ИМЕЕТ ЗНАЧЕНИЕ','История, которая помогает планировать','Культуры назначаете вы. Проверки севооборота используют вашу историю и доступные климатические наблюдения.',`<button class="btn" data-action="add-season">${icon('plus')}Добавить сезон</button><button class="btn primary" data-action="import">Импорт полей</button>`);html+=farm.fields.length?`<div class="notice">Нажмите на ячейку, чтобы назначить культуру. История сохраняется в браузере; экспортируйте резервную копию перед очисткой данных.</div><div class="table-wrap"><table><thead><tr><th>Поле / площадь</th>${farm.seasons.map(s=>`<th>Сезон ${s.year}</th>`).join('')}</tr></thead><tbody>${farm.fields.map(f=>`<tr><td><button class="field-title" data-action="select-field" data-id="${esc(f.id)}">${esc(f.name)}</button><span class="field-sub">${num(f.areaHa)} га</span></td>${farm.seasons.map(s=>{const p=planting(f.id,s.id),c=cropById(p?.cropId??'');return `<td><button class="matrix-cell ${p?'':'unassigned'}" data-action="assign" data-id="${esc(f.id)}" data-year="${s.id}">${c?`<span class="crop-dot" style="background:${esc(c.color)}"></span>${esc(c.name)}`:'＋ Назначить'}</button></td>`;}).join('')}</tr>`).join('')}</tbody></table></div>`:emptyFields();}
if(route==='/plan'){html=heading('ИЗ НАМЕРЕНИЙ — В ПЛАН','Баланс площадей','Задайте целевые площади. Сначала увидите предложение, затем решите, применять ли его. Никаких скрытых изменений.');html+=farm.fields.length?`<div class="card"><h2>Бюджет культур · ${esc(season)}</h2><p class="card-description">Доступно ${num(farm.fields.reduce((s,f)=>s+f.areaHa,0))} га. Распределяются только целые поля. Допуск ±5% может оказаться недостижим.</p><form data-form="budget"><div class="budget-grid">${CROPS.map(c=>`<div class="budget-row"><label for="budget-${c.id}"><span class="crop-dot" style="background:${esc(c.color)}"></span>${esc(c.name)}</label><div><input id="budget-${c.id}" name="${c.id}" type="number" min="0" step="any" value="${Number((farm.budgets[c.id]??0).toFixed(2))}" aria-label="Площадь ${esc(c.name)}, га"> <span class="field-sub" style="display:inline">га</span></div></div>`).join('')}</div><div class="form-actions"><button class="btn primary" type="submit">Рассчитать предложение ↗</button></div></form></div>${preview?`<div class="card plan-preview"><div class="source-name"><h2>Предложение · ${preview.changes.length} изменений</h2><span class="result-badge ${preview.withinTolerance?'good':'warning'}">${preview.withinTolerance?'Допуск ±5% соблюдён':'Допуск ±5% не достигнут'}</span></div><p class="card-description">${preview.notes.map(esc).join('<br>')}</p>${preview.changes.map(c=>`<div class="risk-row">${esc(farm.fields.find(f=>f.id===c.fieldId)?.name)} <span class="field-sub">${esc(cropById(c.before??'')?.name??'Не назначено')} → ${esc(cropById(c.after)?.name)}</span></div>`).join('')}<div class="form-actions"><button class="btn" data-action="dismiss-preview">Оставить текущий план</button><button class="btn primary" data-action="apply-plan" ${preview.changes.length?'':'disabled'}>Применить ${preview.changes.length} изменений</button></div></div>`:''}`:emptyFields();}
if(route==='/risks'){const findings=farm.fields.flatMap(f=>evaluateField(f.id,season,state()).map(x=>({...x,fieldName:f.name})));html=heading('ПРЕДУПРЕДИТЬ, А НЕ УГАДАТЬ','Проверка рисков','Правила севооборота отделены от данных NASA. Отсутствие наблюдений не означает отсутствие риска.',`<button class="btn primary" data-action="risks-refresh">${icon('refresh')}Обновить NASA</button>`);html+=`<div class="card"><h2>Севооборот · ${esc(season)}</h2><p class="card-description">Агрономические правила — эвристики. Это не персональная агрономическая рекомендация.</p>${findings.length?findings.map(f=>`<div class="finding ${f.severity}"><span class="finding-mark"></span><div><strong>${esc(f.fieldName)}</strong> · ${esc(f.message)}<small>${esc(f.suggestion??'')}<br>${esc(f.source.datasetId)}</small></div></div>`).join(''):`<div class="notice" style="margin:20px 0 0">${farm.fields.length?'По введённой истории нет активных замечаний. Климатическая проверка выполняется только после загрузки POWER для выбранного поля.':'Для проверки севооборота добавьте поля и историю культур.'}</div>`}</div><div class="risk-grid"><div class="card"><h2>Термоаномалии · FIRMS</h2><p class="card-description">VIIRS SNPP NRT · последние 3 дня · область хозяйства. Детекция не равна пожару на поле.</p>${firmsData?.data?firmsData.data.length?firmsData.data.slice(0,30).map(f=>`<div class="risk-row">${esc(f.date)} · ${num(f.lat,4)}, ${num(f.lon,4)}<small>FRP ${num(f.frp)} МВт · confidence ${esc(f.confidence)}</small></div>`).join(''):'<div class="notice" style="margin-top:20px">В ответе FIRMS нет термоаномалий в этой области. Это не гарантия отсутствия пожаров.</div>':`<div class="source-result" style="margin-top:20px">${esc(firmsData?.error?.message??'Нажмите «Обновить NASA». Для FIRMS нужен серверный ключ.')}</div>`}${sourceMeta(firmsData)}</div><div class="card"><h2>Природные события · EONET</h2><p class="card-description">События в области хозяйства за 30 дней. EONET не является службой локального прогноза.</p>${eonetData?.data?eonetData.data.length?eonetData.data.slice(0,30).map(e=>`<div class="risk-row"><a href="${safeHref(e.url)}" target="_blank" rel="noopener noreferrer">${esc(e.title)} ↗</a><small>${esc(e.date??'Дата не указана')} · ${esc(e.categories.join(', '))}</small></div>`).join(''):'<div class="notice" style="margin-top:20px">EONET не вернул событий в выбранной области.</div>':`<div class="source-result" style="margin-top:20px">${esc(eonetData?.error?.message??'Запрос ещё не выполнен.')}</div>`}${sourceMeta(eonetData)}</div></div>`;}
if(route==='/sources'){html=heading('ДОВЕРИЕ НАЧИНАЕТСЯ С ИСТОЧНИКА','Данные без чёрного ящика','Каждый источник проверяется реальным запросом с вашего локального сервера. Статус не подменяется тестовыми значениями.',`<button class="btn primary" data-action="diagnose" ${sourceBusy?'disabled':''}>${icon('refresh')}${sourceBusy?'Проверяем подключения…':'Проверить все источники'}</button>`);html+='<div class="notice"><strong>NASA не предоставляет границы ваших полей и историю посевов через эти сервисы.</strong> POWER — региональные климатические данные, GIBS и Worldview — изображения, FIRMS и EONET — события, CMR — каталог метаданных.</div><div class="cards-grid">';const descriptions:Record<string,string>={power:'Температура, осадки, влажность корневого слоя, радиация и ветер. Источник модели и временной стандарт берутся из ответа POWER, а не из фиксированной подписи. Это не датчики поля.',gibs:'Спутниковые растровые слои и каталог доступных дат WMTS. NDVI MODIS Terra 250 м — ежедневный rolling-8-day продукт.',worldview:'Статический снимок выбранной области и даты. Отдельный сервис; доступность проверяется независимо от GIBS.',firms:'Термоаномалии VIIRS. Нужен бесплатный FIRMS MAP_KEY на сервере. Ключ не отправляется в браузер.',eonet:'Каталог природных событий. Пустой ответ означает отсутствие записей в каталоге, а не доказанную безопасность.',cmr:'Метаданные спутниковых коллекций: названия, версии и ссылки. Не сервис измерений вашего поля.'};for(const source of SOURCES.filter(s=>s.id!=='rules')){const result=sourceReport[source.id];html+=`<article class="card source-card"><div class="source-name"><div><h2>${esc(source.name)}</h2><small>${esc(source.datasetId)}</small></div><span class="result-badge ${result?.state==='fresh'?'good':result?'warning':''}">${esc(result?({fresh:'Отвечает',partial:'Есть пропуски',stale:'Кэш',key:'Нужен ключ',error:'Ошибка'}[result.state]??result.state):'Не проверен')}</span></div><p class="card-description">${esc(descriptions[source.id]??source.resolution)}</p><div class="source-result">${esc(result?.detail??'Результат появится после запроса.')}<div class="source-caption">${result?`Проверено: ${esc(new Date(result.at).toLocaleString('ru'))}`:'Исторические даты и задержки публикации зависят от продукта.'}</div></div><div class="card-actions"><button class="btn small" data-action="source-check" data-source="${source.id}" ${sourceBusy?'disabled':''}>Проверить</button>${source.id==='worldview'?'<button class="btn small" data-action="snapshot">Открыть снимок</button>':''}<a href="${safeHref(source.url)}" target="_blank" rel="noopener noreferrer">Источник ↗</a></div></article>`;}html+='</div><div class="form-actions"><button class="btn" data-action="copy-diagnostics">Скопировать диагностику</button></div>';}
if(route==='/settings'){html=heading('ВАШЕ РАБОЧЕЕ ПРОСТРАНСТВО','Настройки','Поля и история принадлежат вам. Приложение не отправляет их в облачное хранилище; NASA получает координаты запрошенной территории.');html+=`<div class="card settings-section"><h2>Данные хозяйства</h2><div class="settings-row"><div><strong>Импорт границ GeoJSON</strong><p>FeatureCollection с Polygon, до 500 полей. Существующие поля не удаляются. MultiPolygon нужно предварительно разделить.</p></div><button class="btn" data-action="import">${icon('upload')}Импортировать</button></div><div class="settings-row"><div><strong>Резервная копия целиком</strong><p>Границы, сезоны, назначения, бюджеты и настройки правил. Храните копию вне браузера.</p></div><button class="btn" data-action="backup">${icon('download')}Скачать JSON</button></div><div class="settings-row"><div><strong>Восстановить резервную копию</strong><p>Заменяет текущее хозяйство после подтверждения. Демо-архивы не загружаются в рабочий режим.</p></div><button class="btn" data-action="restore">Восстановить</button></div><div class="settings-row"><div><strong>Состоян��е сохранения</strong><p>${esc(storageFailure||'localStorage включён. Изменения сохраняются после каждого действия. Доступны 20 шагов Undo в текущей сессии.')}</p></div><span class="result-badge ${storageFailure?'warning':'good'}">${storageFailure?'Проверьте':'Локально'}</span></div></div><div class="card settings-section"><h2>Внешний вид и сезон</h2><div class="settings-row"><div><strong>Цветовая тема</strong><p>Спокойная светлая или контрастная тёмная. Карта сохраняет цвета источника.</p></div><select id="theme" aria-label="Цветовая тема"><option value="light" ${document.body.dataset.theme!=='dark'?'selected':''}>Светлая</option><option value="dark" ${document.body.dataset.theme==='dark'?'selected':''}>Тёмная</option></select></div><div class="settings-row"><div><strong>Добавить сезон</strong><p>История других лет останется нетронутой. Будущим сезонам не присваиваются выдуманные климатические наблюдения.</p></div><button class="btn" data-action="add-season">Добавить сезон</button></div></div><div class="card settings-section"><h2>Подключение NASA</h2><div class="settings-row"><div><strong>Живая диагностика</strong><p>Проверит карту и NASA через тот же сервер, который обслуживает приложение. Подробности ошибок доступны в разделе источников.</p></div><button class="btn primary" data-action="diagnose">Проверить подключения</button></div><div class="settings-row"><div><strong>Ключ FIRMS</strong><p>Создайте рядом с server.mjs файл .env.local со строкой FIRMS_MAP_KEY=ваш_ключ и перезапустите сервер. Не вводите ключ в браузере или чате. Остальные источники не требуют этого ключа.</p></div><a class="btn" href="https://firms.modaps.eosdis.nasa.gov/api/area/" target="_blank" rel="noopener noreferrer">Получить ключ ↗</a></div></div><div class="card"><h2>Очистка</h2><p class="card-description">Перед очисткой экспортируйте резервную копию. Сброс создаёт пустое хозяйство — не демо-модель.</p><div class="form-actions"><button class="btn danger" data-action="clear">Удалить данные хозяйства</button></div></div>`;}
$('#other-page').innerHTML=html;paintIcons($('#other-page'));}
function sourceMeta(body:ApiEnvelope<unknown>|null){return body?`<div class="source-caption">${esc(body.source.datasetId)} · ${esc(body.status)}<br>${body.cache.fetchedAt?'Получено '+esc(new Date(body.cache.fetchedAt).toLocaleString('ru')):'Успешного ответа ещё нет'}</div>`:'';}
function showModal(title:string,body:string,footer=''){const modal=$<HTMLDialogElement>('#modal');if(modal.open)modal.close();modal.innerHTML=`<div class="modal-heading"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="Закрыть">${icon('close')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;modal.showModal();if(motionAllowed())modal.animate([{opacity:0,transform:'translateY(14px) scale(.975)'},{opacity:1,transform:'translateY(0) scale(1)'}],{duration:300,easing:'cubic-bezier(.16,1,.3,1)'});paintIcons(modal);}
function cropOptions(current=''){return '<option value="">Не назначать</option>'+CROPS.map(c=>`<option value="${c.id}" ${current===c.id?'selected':''}>${esc(c.name)}</option>`).join('');}
function editField(id?:string,geometry?:Polygon){const field=farm.fields.find(f=>f.id===id);const p=field?planting(field.id):undefined;const geom=geometry??field?.geometry;if(!geom)return;showModal(field?'Моё поле':'Новое поле',`<form id="field-form" class="modal-form" data-form="field"><input name="id" type="hidden" value="${esc(field?.id??'')}"><input name="geometry" type="hidden" value="${esc(JSON.stringify(geom))}"><label>Название поля<input name="name" required maxlength="100" value="${esc(field?.name??`Поле ${farm.fields.length+1}`)}" autofocus></label><div class="notice" style="margin:0">Площадь по контуру: <strong>${num(areaHa(geom))} га</strong>. Контур введён вами, не автоматически определён NASA.</div><label>Культура · ${esc(season)}<select name="cropId">${cropOptions(p?.cropId)}</select></label><div class="form-two"><label>Дата посева<input name="plantedAt" type="date" value="${esc(p?.plantedAt??'')}"></label><label>Дата уборки<input name="harvestedAt" type="date" value="${esc(p?.harvestedAt??'')}"></label></div><label>Сорт · необязательно<input name="variety" maxlength="100" value="${esc(p?.variety??'')}"></label><div id="form-error" class="form-error" hidden></div></form>`,`${field?`<button class="btn danger" data-action="delete-field" data-id="${esc(field.id)}">Удалить</button><button class="btn" data-action="redraw" data-id="${esc(field.id)}">Перерисовать</button>`:'<button class="btn" data-action="close-modal">Отмена</button>'}<button class="btn primary" type="submit" form="field-form">Сохранить поле</button>`);}
function assignModal(id:string,year:string){const field=farm.fields.find(f=>f.id===id)!;const p=planting(id,year);showModal('Назначение культуры',`<form id="assign-form" class="modal-form" data-form="assign"><input name="id" type="hidden" value="${esc(id)}"><input name="year" type="hidden" value="${esc(year)}"><p><strong>${esc(field.name)}</strong> · ${num(field.areaHa)} га · сезон ${esc(year)}</p><label>Культура<select name="cropId">${cropOptions(p?.cropId)}</select></label><div class="form-two"><label>Посев<input name="plantedAt" type="date" value="${esc(p?.plantedAt??'')}"></label><label>Уборка<input name="harvestedAt" type="date" value="${esc(p?.harvestedAt??'')}"></label></div><label>Сорт<input name="variety" maxlength="100" value="${esc(p?.variety??'')}"></label><div id="form-error" class="form-error" hidden></div></form>`,`<button class="btn" data-action="close-modal">Отмена</button><button class="btn primary" type="submit" form="assign-form">Сохранить</button>`);}
function setPlanting(next:FarmSnapshot,id:string,year:string,data:FormData){const previous=next.plantings.find(p=>p.fieldId===id&&p.seasonId===year);next.plantings=next.plantings.filter(p=>!(p.fieldId===id&&p.seasonId===year));const cropId=String(data.get('cropId')??'');if(!cropId)return;next.plantings.push({id:previous?.id??crypto.randomUUID(),fieldId:id,seasonId:year,cropId,areaHa:next.fields.find(f=>f.id===id)!.areaHa,...(data.get('plantedAt')?{plantedAt:String(data.get('plantedAt'))}:{}),...(data.get('harvestedAt')?{harvestedAt:String(data.get('harvestedAt'))}:{}),...(data.get('variety')?{variety:String(data.get('variety'))}:{})});}
function beginDraw(id?:string){if(!mapReady){navigate('/');toast('Для рисования нужна загруженная карта. Можно импортировать GeoJSON без неё.');return;}navigate('/');$<HTMLDialogElement>('#modal').close();editingGeometry=id??null;drawing=true;vertices=[];$('.map-stage').classList.add('drawing');$('#drawing-bar').hidden=false;$('#map-empty').hidden=true;$('#fields-list').hidden=true;map!.doubleClickZoom.disable();map!.getCanvas().style.cursor='crosshair';updateDrawing();}
function cancelDraw(){drawing=false;vertices=[];editingGeometry=null;$('.map-stage').classList.remove('drawing');$('#drawing-bar').hidden=true;map?.doubleClickZoom.enable();if(map)map.getCanvas().style.cursor='';updateDrawing();$('#map-empty').hidden=farm.fields.length>0;}
function finishDraw(){if(vertices.length<3){toast('Отметьте минимум три угла поля.');return;}const geometry:Polygon={type:'Polygon',coordinates:[[...vertices,vertices[0]]]};if(!validPolygon(geometry)){toast('Контур самопересекается или слишком мал. Исправьте точки.');return;}const id=editingGeometry;cancelDraw();editField(id??undefined,geometry);}
function fit(){if(!mapReady)return;if(farm.fields.length){const b=bbox(farm.fields,.006);map!.fitBounds([[b[0],b[1]],[b[2],b[3]]],{padding:75,maxZoom:14,duration:700});}else map!.flyTo({center:point,zoom:9,duration:700});}
function selectField(id:string){selectedId=id;const field=chosen();if(!field)return;point=centroid(field.geometry);navigate('/');$('#fields-list').hidden=true;render();if(mapReady)map!.flyTo({center:point,zoom:Math.max(11,map!.getZoom()),duration:700});loadClimate();}
function mapFailure(title:string,detail:string){mapReady=false;$('.map-stage').classList.remove('ready');$('#map-state').hidden=false;$('#map-state').innerHTML=`<div class="map-state-card"><span class="state-icon">${icon('map')}</span><h2>${esc(title)}</h2><p>Не удалось получить настоящую карту. Вымышленная подложка не показывается. Импорт и история полей продолжают работать.</p><div class="failure-code">${esc(detail.slice(0,220))}</div><button class="btn primary" data-action="retry-map">Повторить</button><button class="btn" data-action="diagnose">Диагностика</button></div>`;report('map','error',detail);}
async function loadMapEngine(){if(window.maplibregl)return;const origins=['https://cdn.jsdelivr.net/npm/maplibre-gl@5.6.1/dist','https://unpkg.com/maplibre-gl@5.6.1/dist'];for(const base of origins){const css=document.createElement('link');css.rel='stylesheet';css.href=base+'/maplibre-gl.css';document.head.append(css);try{await new Promise<void>((resolve,reject)=>{const script=document.createElement('script');const timer=setTimeout(()=>{script.remove();reject(new Error('Таймаут загрузки MapLibre'));},10000);script.src=base+'/maplibre-gl.js';script.onload=()=>{clearTimeout(timer);window.maplibregl?resolve():reject(new Error('Модуль карты не инициализирован'));};script.onerror=()=>{clearTimeout(timer);script.remove();reject(new Error('CDN карты недоступен'));};document.head.append(script);});return;}catch{css.remove();}}throw new Error('Не удалось получить MapLibre с двух CDN. Проверьте интернет и блокировщики.');}
async function initMap(){map?.remove();map=null;mapReady=false;$('.map-stage').classList.remove('ready');$('#map-state').hidden=false;$('#map-state').innerHTML='<div class="map-state-card"><span class="state-icon">'+icon('map')+'</span><h2>Подключаем карту</h2><p>Географическая подложка OpenFreeMap.<br>Без демо-полей и вымышленных данных.</p><span class="loading-line"></span></div>';try{await loadMapEngine();map=new window.maplibregl!.Map({container:$('#map'),style:location.origin+'/api/maps/styles/positron',center:point,zoom:8.6,maxZoom:18,attributionControl:{compact:true}});const instance=map;let lastError='Сервер не получил стиль или тайлы OpenFreeMap.';const timer=setTimeout(()=>{if(!mapReady&&map===instance)mapFailure('Подложка не загрузилась',lastError);},30000);map.on('error',event=>{lastError=event.error?.message??lastError;});map.on('load',()=>{if(map!==instance)return;clearTimeout(timer);try{map!.addSource('fields',{type:'geojson',data:geoData()});map!.addLayer({id:'field-fill',type:'fill',source:'fields',paint:{'fill-color':['get','color'],'fill-opacity':.23}});map!.addLayer({id:'field-outline',type:'line',source:'fields',paint:{'line-color':'#526C44','line-width':1.5}});map!.addLayer({id:'field-selected',type:'line',source:'fields',filter:['==',['get','id'],selectedId??''],paint:{'line-color':'#245F35','line-width':3}});map!.addLayer({id:'field-label',type:'symbol',source:'fields',minzoom:10,layout:{'text-field':['get','label'],'text-font':['Noto Sans Regular'],'text-size':12,'text-max-width':10,'text-padding':8},paint:{'text-color':'#172D17','text-halo-color':'#FFF','text-halo-width':1.5}});map!.addSource('drawing',{type:'geojson',data:{type:'FeatureCollection',features:[]}});map!.addLayer({id:'drawing-line',type:'line',source:'drawing',paint:{'line-color':'#246D39','line-width':3}});map!.addLayer({id:'drawing-points',type:'circle',source:'drawing',filter:['==',['geometry-type'],'Point'],paint:{'circle-radius':5,'circle-color':'#246D39','circle-stroke-color':'#FFF','circle-stroke-width':2}});mapReady=true;$('#map-state').hidden=true;$('.map-stage').classList.add('ready');report('map','fresh','Стиль и начальные тайлы карты загружены в браузере');if(farm.fields.length)fit();if(layer!=='none')applyLayer(layer);render();}catch(error){mapFailure('Ошибка отображения карты',error instanceof Error?error.message:'Неизвестная ошибка');}});map.on('click',event=>{if(!mapReady)return;const pos:Position=[event.lngLat.lng,event.lngLat.lat];if(drawing){vertices.push(pos);updateDrawing();return;}const hit=map!.queryRenderedFeatures(event.point,{layers:['field-fill']})[0];if(hit?.properties?.id){selectField(String(hit.properties.id));return;}selectedId=null;point=pos;render();loadClimate();if(layer!=='none')probeImage();});}catch(error){mapFailure('Не удалось открыть карту',error instanceof Error?error.message:'Проверьте WebGL и аппаратное ускорение.');}}
const trueColor='MODIS_Terra_CorrectedReflectance_TrueColor';
async function applyLayer(id:string){layer=id;document.querySelectorAll<HTMLElement>('[data-layer]').forEach(b=>b.classList.toggle('active',b.dataset.layer===id));if(!mapReady){if(id!=='none')toast('Спутниковый слой включится после загрузки карты.');return;}if(map!.getLayer('nasa-raster'))map!.removeLayer('nasa-raster');if(map!.getSource('nasa'))map!.removeSource('nasa');if(id==='none'){$('#imagery-status').textContent='Выберите спутниковый слой и дату. Измерения NDVI не подставляются.';$('#map-caption').textContent='OpenFreeMap · © OpenStreetMap contributors';return;}map!.addSource('nasa',{type:'raster',tiles:[`${location.origin}/api/nasa/gibs/tile/${id}/${imageDate}/{z}/{y}/{x}`],tileSize:256,maxzoom:9,attribution:'NASA EOSDIS GIBS'});map!.addLayer({id:'nasa-raster',type:'raster',source:'nasa',paint:{'raster-opacity':.87,'raster-fade-duration':300}},'field-fill');$('#map-caption').textContent=`NASA GIBS · ${imageDate} · ${id.includes('NDVI')?'NDVI 250 м · rolling 8 дней':'MODIS Terra · True color'} · не классификация культур`;await probeImage();}
let imageToken=0;
async function probeImage(){const token=++imageToken;if(layer==='none')return;$('#imagery-status').textContent='Проверяем спутниковый тайл в выбранной точке…';const z=8,n=2**z,xf=(point[0]+180)/360*n,lat=Math.max(-85,Math.min(85,point[1]))*Math.PI/180,yf=(1-Math.asinh(Math.tan(lat))/Math.PI)/2*n,x=Math.floor(xf),y=Math.floor(yf);try{const r=await fetch(`/api/nasa/gibs/tile/${layer}/${imageDate}/${z}/${y}/${x}`,{signal:AbortSignal.timeout(60000)});if(!r.ok){const b=await r.json();throw new Error(b.error?.message??'Снимок недоступен');}const bitmap=await createImageBitmap(await r.blob());const canvas=document.createElement('canvas');canvas.width=bitmap.width;canvas.height=bitmap.height;const context=canvas.getContext('2d')!;context.drawImage(bitmap,0,0);const alpha=context.getImageData(Math.min(bitmap.width-1,Math.floor((xf-x)*bitmap.width)),Math.min(bitmap.height-1,Math.floor((yf-y)*bitmap.height)),1,1).data[3];bitmap.close();if(token!==imageToken)return;const stale=r.headers.get('X-NASA-Status')==='stale';$('#imagery-status').textContent=`${alpha?'В выбранной точке есть пиксель изображения.':'В выбранной точке нет пикселя изображения.'} Дата ${imageDate}.${stale?' Показан последний успешный ответ из кэша.':''} Числовой NDVI из цвета не рассчитывается.`;report('gibs',stale?'stale':'fresh',`Тайл за ${imageDate} получен${alpha?'':' · точка прозрачная'}`);}catch(error){if(token!==imageToken)return;const message=error instanceof Error?error.message:'Нет снимка';$('#imagery-status').textContent=message;report('gibs','error',message);}}
function region(){if(farm.fields.length)return bbox(farm.fields,.1).join(',');return [Math.max(-180,point[0]-.5),Math.max(-85,point[1]-.5),Math.min(180,point[0]+.5),Math.min(85,point[1]+.5)].join(',');}
async function loadRisks(){toast('Запрашиваем FIRMS и EONET для области хозяйства…');await Promise.allSettled([api<FireDetection[]>('firms','/api/nasa/firms?bbox='+region()+'&days=3').then(v=>firmsData=v).catch(error=>report('firms','error',String(error))),api<NaturalEvent[]>('eonet','/api/nasa/eonet?bbox='+region()+'&days=30').then(v=>eonetData=v).catch(error=>report('eonet','error',String(error)))]);if(route==='/risks')renderOther();}
async function checkSource(id:string){try{if(id==='power'){await loadClimate();return;}if(id==='gibs'){const b=await api<GIBSLayer[]>('gibs','/api/nasa/gibs/capabilities');if(b.data)report('gibs',b.status,`Каталог: ${b.data.length} поддерживаемых слоя; даты взяты из WMTS`);return;}if(id==='cmr'){const b=await api<unknown[]>('cmr','/api/nasa/cmr?query=MOD13Q4N&pageSize=3');if(b.data)report('cmr',b.status,`Получено ${b.data.length} коллекций по MOD13Q4N`);return;}if(id==='firms'){firmsData=await api<FireDetection[]>('firms','/api/nasa/firms?bbox='+region()+'&days=3');return;}if(id==='eonet'){eonetData=await api<NaturalEvent[]>('eonet','/api/nasa/eonet?bbox='+region()+'&days=30');return;}if(id==='worldview'){const response=await fetch(snapshotRequest(),{signal:AbortSignal.timeout(60000)});if(!response.ok){const b=await response.json();throw new Error(b.error?.message??'Worldview недоступен');}const blob=await response.blob();if(!blob.type.startsWith('image/'))throw new Error('Ответ Worldview не является изображением');report('worldview',response.headers.get('X-NASA-Status')==='stale'?'stale':'fresh',`Снимок за ${imageDate} получен · ${num(blob.size/1024,0)} КБ`);return;}}catch(error){report(id,'error',error instanceof Error?error.message:'Ошибка запроса');}finally{if(route==='/sources'||route==='/risks')renderOther();}}
const snapshotRequest=()=>`/api/nasa/worldview?bbox=${region()}&date=${imageDate}&layer=${trueColor}&width=1000&height=700`;
async function diagnose(){navigate('/sources');if(sourceBusy)return;sourceBusy=true;renderOther();const checks=['power','gibs','worldview','firms','eonet','cmr'];await Promise.allSettled(checks.map(checkSource));sourceBusy=false;renderOther();toast('Проверка завершена. Статусы отражают ответы вашего сервера.');}
async function snapshot(){toast('Запрашиваем Worldview…');try{const r=await fetch(snapshotRequest(),{signal:AbortSignal.timeout(60000)});if(!r.ok){const b=await r.json();throw new Error(b.error?.message??'Снимок недоступен');}const blob=await r.blob();if(!blob.type.startsWith('image/'))throw new Error('Сервер не вернул изображение');if(snapshotUrl)URL.revokeObjectURL(snapshotUrl);snapshotUrl=URL.createObjectURL(blob);showModal('NASA Worldview',`<p>Дата ${esc(imageDate)} · MODIS Terra · область ${esc(region())}. Это статический снимок, не распознавание полей.</p><img class="snapshot" src="${snapshotUrl}" alt="Реальный спутниковый снимок NASA Worldview за ${esc(imageDate)}">`,`<a class="btn primary" href="${snapshotUrl}" download="NASA-Worldview-${imageDate}.png">Скачать PNG</a>`);report('worldview','fresh','Изображение получено');}catch(error){toast(error instanceof Error?error.message:'Снимок недоступен');}}
function command(){showModal('Найти поле или точку',`<label class="modal-form">Название поля или координаты<input id="command-query" placeholder="47.979811, 67.243753" autofocus autocomplete="off"></label><p class="form-help" style="margin-top:12px">Координаты: широта, долгота. Поиск по названиям — только среди ваших полей.</p><div id="command-results" class="command-results"></div>`);$('#command-query').addEventListener('input',()=>{const q=$<HTMLInputElement>('#command-query').value.trim(),parts=q.split(/[,;\s]+/).filter(Boolean).map(Number);const coordinates=parts.length===2&&parts.every(Number.isFinite)&&Math.abs(parts[0])<=85&&Math.abs(parts[1])<=180;$('#command-results').innerHTML=(coordinates?`<button class="command-result" data-action="goto" data-lat="${parts[0]}" data-lon="${parts[1]}">Перейти к ${num(parts[0],5)}, ${num(parts[1],5)} ↗</button>`:'')+farm.fields.filter(f=>f.name.toLocaleLowerCase('ru').includes(q.toLocaleLowerCase('ru'))).slice(0,12).map(f=>`<button class="command-result" data-action="select-field" data-id="${esc(f.id)}">${esc(f.name)} · ${num(f.areaHa)} га</button>`).join('');});$('#command-query').dispatchEvent(new Event('input'));}
function addSeason(){const next=Math.max(...farm.seasons.map(s=>s.year))+1;showModal('Новый сезон',`<form id="season-form" class="modal-form" data-form="season"><label>Год<input type="number" name="year" min="1982" max="2100" required value="${next}"></label><p class="form-help">Новый сезон будет пустым. Культуры и наблюдения не копируются автоматически.</p><div id="form-error" class="form-error" hidden></div></form>`,`<button class="btn primary" form="season-form" type="submit">Добавить</button>`);}
function formError(message:string){const target=$('#form-error');if(target){target.hidden=false;target.textContent=message;}else toast(message);}
document.addEventListener('submit',event=>{const form=event.target as HTMLFormElement;if(!form.dataset.form)return;event.preventDefault();const data=new FormData(form);try{if(['field','assign'].includes(form.dataset.form)){const start=String(data.get('plantedAt')??''),end=String(data.get('harvestedAt')??'');if(start&&end&&start>end){formError('Дата уборки не может предшествовать посеву.');return;}}if(form.dataset.form==='field'){const id=String(data.get('id')??'')||crypto.randomUUID(),geometry=JSON.parse(String(data.get('geometry'))) as Polygon;if(!validPolygon(geometry)){formError('Неверный контур');return;}const saved=change(next=>{const existing=next.fields.find(f=>f.id===id);const field:Field={id,name:String(data.get('name')).trim(),geometry,areaHa:areaHa(geometry),color:existing?.color??'#76916D',...(existing?.groupId?{groupId:existing.groupId}:{})};next.fields=[...next.fields.filter(f=>f.id!==id),field];next.plantings=next.plantings.map(p=>p.fieldId===id?{...p,areaHa:field.areaHa}:p);setPlanting(next,id,season,data);});if(saved){$<HTMLDialogElement>('#modal').close();selectField(id);toast('Поле сохранено в этом браузере');}}
if(form.dataset.form==='assign'){const id=String(data.get('id')),year=String(data.get('year'));if(change(next=>setPlanting(next,id,year,data))){$<HTMLDialogElement>('#modal').close();toast('Назначение сохранено');}}
if(form.dataset.form==='budget'){const budgets=Object.fromEntries(CROPS.map(c=>[c.id,Number(data.get(c.id)??0)]));if(Object.values(budgets).some(v=>!Number.isFinite(v)||v<0)){toast('Площади должны быть неотрицательными числами');return;}change(next=>{next.budgets=budgets;});preview=allocate(state(),season);renderOther();}
if(form.dataset.form==='season'){const year=Number(data.get('year'));if(!Number.isInteger(year)||year<1982||year>2100||farm.seasons.some(s=>s.year===year)){formError('Укажите уникальный год от 1982 до 2100');return;}if(change(next=>{next.seasons.push({id:String(year),year,startsAt:`${year}-04-01`,endsAt:`${year}-10-31`});next.seasons.sort((a,b)=>a.year-b.year);})){season=String(year);safeStorage.set('appname-live-season',season);$<HTMLDialogElement>('#modal').close();render();}}
}catch(error){formError(error instanceof Error?error.message:'Не удалось сохранить');}});
document.addEventListener('click',async event=>{const target=(event.target as Element).closest<HTMLElement>('[data-action],[data-route],[data-layer]');if(!target)return;if(target.dataset.route){event.preventDefault();navigate(target.dataset.route);return;}if(target.dataset.layer){applyLayer(target.dataset.layer);return;}const action=target.dataset.action,id=target.dataset.id;try{switch(action){case'menu':document.body.classList.toggle('nav-open');document.querySelector('.topbar [data-action=menu]')?.setAttribute('aria-expanded',String(document.body.classList.contains('nav-open')));break;case'undo':historyAction('undo');break;case'redo':historyAction('redo');break;case'import':$<HTMLInputElement>('#geo-file').click();break;case'backup':download('AppName-backup.json',JSON.stringify(farm,null,2),'application/json');break;case'restore':$<HTMLInputElement>('#backup-file').click();break;case'export':showModal('Экспорт данных','<p>GeoJSON — границы с историей. CSV — назначения культур с BOM для Excel. Резервная копия — всё хозяйство.</p>','<button class="btn" data-action="export-geo">GeoJSON</button><button class="btn" data-action="export-csv">CSV</button><button class="btn primary" data-action="backup">Всё · JSON</button>');break;case'export-geo':download('AppName-fields.geojson',exportGeojson(farm),'application/geo+json');break;case'export-csv':download('AppName-rotation.csv',exportCsv(farm),'text/csv;charset=utf-8');break;case'fields':$('#fields-list').hidden=!$('#fields-list').hidden;break;case'draw':beginDraw();break;case'finish-draw':finishDraw();break;case'cancel-draw':cancelDraw();break;case'vertex-undo':vertices.pop();updateDrawing();break;case'edit-field':editField(id);break;case'redraw':beginDraw(id);break;case'select-field':$<HTMLDialogElement>('#modal').close();selectField(id!);break;case'assign':assignModal(id!,target.dataset.year!);break;case'delete-field':if(confirm('Удалить поле и все его назначения? Действие можно отменить в текущей сессии.')){change(next=>{next.fields=next.fields.filter(f=>f.id!==id);next.plantings=next.plantings.filter(p=>p.fieldId!==id);});selectedId=null;$<HTMLDialogElement>('#modal').close();render();loadClimate();}break;case'close-modal':await closeModalAnimated();break;case'zoom-in':map?.zoomIn();break;case'zoom-out':map?.zoomOut();break;case'fit':fit();break;case'locate':navigator.geolocation.getCurrentPosition(pos=>{point=[pos.coords.longitude,pos.coords.latitude];selectedId=null;map?.flyTo({center:point,zoom:11});loadClimate();},()=>toast('Местоположение недоступно. Введите координаты через поиск.'),{timeout:10000});break;case'command':command();break;case'goto':point=[Number(target.dataset.lon),Number(target.dataset.lat)];selectedId=null;$<HTMLDialogElement>('#modal').close();navigate('/');map?.flyTo({center:point,zoom:11});loadClimate();break;case'retry-map':initMap();break;case'refresh-climate':loadClimate();break;case'satellite':applyLayer(trueColor);break;case'date-prev':case'date-next':{const next=dateOffset(imageDate,action==='date-prev'?-1:1);if(next>today())return;imageDate=next;$<HTMLInputElement>('#image-date').value=imageDate;if(layer!=='none')applyLayer(layer);if(!chosen())loadClimate();break;}case'risks-refresh':loadRisks();break;case'diagnose':diagnose();break;case'source-check':checkSource(target.dataset.source!);break;case'snapshot':snapshot();break;case'copy-diagnostics':await navigator.clipboard.writeText(JSON.stringify({application:'AppName Live 0.2.3',checkedAt:new Date().toISOString(),coordinates:point,imageDate,results:sourceReport},null,2));toast('Диагностика скопирована. Ключей и полей в отчёте нет.');break;case'add-season':addSeason();break;case'dismiss-preview':preview=null;renderOther();break;case'apply-plan':{if(!preview)return;const changes=preview.changes;change(next=>{for(const c of changes){const field=next.fields.find(f=>f.id===c.fieldId)!;const old=next.plantings.find(p=>p.fieldId===field.id&&p.seasonId===season);next.plantings=next.plantings.filter(p=>!(p.fieldId===field.id&&p.seasonId===season));next.plantings.push({...old,id:old?.id??crypto.randomUUID(),fieldId:field.id,seasonId:season,cropId:c.after,areaHa:field.areaHa});}});toast('План применён. Undo отменит всё распределение одним действием.');break;}case'clear':showModal('Удалить хозяйство?','<p>Будут удалены границы, история и бюджеты текущего рабочего пространства. Рекомендуем сначала скачать резервную копию. Старые демо-данные из других версий не затрагиваются.</p>','<button class="btn" data-action="backup">Скачать копию</button><button class="btn danger" data-action="clear-confirm">Удалить хозяйство</button>');break;case'clear-confirm':change(next=>Object.assign(next,createWorkspace()));selectedId=null;climate={};activeClimate=null;$<HTMLDialogElement>('#modal').close();render();toast('Создано пустое хозяйство');break;}}catch(error){toast(error instanceof Error?error.message:'Действие не выполнено');}});
$<HTMLInputElement>('#geo-file').addEventListener('change',async event=>{const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;try{const fields=parseFieldsGeojson(await file.text());const unique=fields.filter(f=>!farm.fields.some(existing=>JSON.stringify(existing.geometry)===JSON.stringify(f.geometry)));if(farm.fields.length+unique.length>500)throw new Error('Лимит — 500 полей в хозяйстве.');if(!unique.length){toast('Такие контуры уже есть в хозяйстве.');return;}showModal('Импорт границ',`<p>Файл: <strong>${esc(file.name)}</strong><br>Новых полей: ${unique.length} · ${num(unique.reduce((s,f)=>s+f.areaHa,0))} га.<br>Существующие поля и назначения сохранятся. История культур автоматически не выдумывается.</p>`,`<button class="btn" data-action="close-modal">Отмена</button><button class="btn primary" id="confirm-import">Добавить ${unique.length} полей</button>`);$('#confirm-import').addEventListener('click',()=>{change(next=>{next.fields.push(...unique.map(f=>({...f,id:crypto.randomUUID()})));});$<HTMLDialogElement>('#modal').close();fit();toast('Границы импортированы. Назначьте культуры в разделе истории.');});}catch(error){toast(error instanceof Error?error.message:'Не удалось импортировать файл');}finally{input.value='';}});
$<HTMLInputElement>('#backup-file').addEventListener('change',async event=>{const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;try{if(file.size>5_000_000)throw new Error('Резервная копия больше 5 МБ');const parsed=farmSchema.safeParse(JSON.parse(await file.text()));if(!parsed.success||parsed.data.demo)throw new Error('Нужна корректная резервная копия рабочего хозяйства, не демо.');if(!parsed.data.fields.every(f=>validPolygon(f.geometry)))throw new Error('Архив содержит некорректную геометрию');const problems=integrityProblems(parsed.data);if(problems.length)throw new Error('Архив несогласован: '+problems.slice(0,3).join('; ')+(problems.length>3?` и ещё ${problems.length-3}`:''));if(confirm('Заменить текущее хозяйство резервной копией?')){change(next=>Object.assign(next,parsed.data));selectedId=null;climate={};render();fit();toast('Резервная копия восст��новлена');}}catch(error){toast(error instanceof Error?error.message:'Некорректный архив');}finally{input.value='';}});
$('#season').addEventListener('change',event=>{season=(event.target as HTMLSelectElement).value;safeStorage.set('appname-live-season',season);preview=null;render();loadClimate();});
$('#image-date').addEventListener('change',event=>{const value=(event.target as HTMLInputElement).value;if(!/^\d{4}-\d{2}-\d{2}$/.test(value)||value>today()){toast('Выберите корректную дату, не позднее сегодняшней.');return;}imageDate=value;if(layer!=='none')applyLayer(layer);if(!chosen())loadClimate();});
document.addEventListener('change',event=>{const e=event.target as HTMLSelectElement;if(e.id==='theme'){document.body.dataset.theme=e.value;safeStorage.set('appname-live-theme',e.value);}});
document.addEventListener('keydown',event=>{const typing=(event.target as HTMLElement).matches('input,textarea,select');if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();command();return;}if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='z'&&!typing){event.preventDefault();historyAction(event.shiftKey?'redo':'undo');return;}if(typing||$<HTMLDialogElement>('#modal').open)return;if(event.key==='Escape'){cancelDraw();$('#fields-list').hidden=true;}if(event.key==='Enter'&&drawing)finishDraw();if(event.key.toLowerCase()==='j'||event.key.toLowerCase()==='k'){const index=farm.fields.findIndex(f=>f.id===selectedId),next=event.key.toLowerCase()==='j'?index+1:index-1;const field=farm.fields[(next+farm.fields.length)%farm.fields.length];if(field)selectField(field.id);}if(/^[1-9]$/.test(event.key)&&selectedId){const crop=CROPS[Number(event.key)-1];if(crop){const data=new FormData();data.set('cropId',crop.id);change(next=>setPlanting(next,selectedId!,season,data));toast('Назначена культура: '+crop.name);}}});
window.addEventListener('popstate',()=>{route=location.pathname;renderRoute();enterPage();if(route==='/')map?.resize();});
new ResizeObserver(()=>map?.resize()).observe($('#map'));
$('#modal').addEventListener('close',()=>{if(snapshotUrl){URL.revokeObjectURL(snapshotUrl);snapshotUrl=null;}});
$('#image-date').setAttribute('max',today());$<HTMLInputElement>('#image-date').value=imageDate;
document.body.dataset.theme=safeStorage.get('appname-live-theme')??'light';
paintIcons();render();enterPage();initMap();loadClimate();if(storageFailure)toast(storageFailure);

// Motion is progressive enhancement: no business logic depends on animation completion.
document.addEventListener('pointerdown',event=>{const target=(event.target as Element).closest<HTMLButtonElement>('button');if(!target||target.disabled||!motionAllowed())return;target.animate([{transform:'scale(1)'},{transform:'scale(.97)'},{transform:'scale(1)'}],{duration:240,easing:'cubic-bezier(.2,.8,.2,1)'});});
